// partialy generated by Copilot
import { validatorUtilsMocks, getEmailIsValidMock } from '@pulse/toolbox/mocks'
import { getEmailErrorKey, getPasswordErrorKey } from './LoginClient.utils'

vi.mock('@pulse/toolbox/utils/validator', () => validatorUtilsMocks)

describe('test LoginClient.utils', () => {
  describe('getEmailErrorKey', () => {
    const testCases = [
      {
        email: '',
        isValid: false,
        expected: 'alertMailRequired',
        description: 'should return required key when email is empty',
      },
      {
        email: 'invalid-email',
        isValid: false,
        expected: 'alertMailInvalid',
        description: 'should return invalid key for invalid email',
      },
      {
        email: 'valid.email@example.com',
        isValid: true,
        expected: '',
        description: 'should return an empty string for a valid email',
      },
    ] as const

    it.each(testCases)('$description', ({
      email,
      expected,
      isValid,
    }) => {
      getEmailIsValidMock.mockReturnValue(isValid)

      const result = getEmailErrorKey(email)
      expect(result).toBe(expected)
    })
  })

  describe('getPasswordErrorKey', () => {
    const testCases = [
      {
        password: '',
        expected: 'alertPasswordRequired',
        description: 'should return required key when password is empty',
      },
      {
        password: 'password123',
        expected: '',
        description: 'should return an empty string when password is NOT empty',
      },
    ] as const
    it.each(testCases)('$description', ({
      password,
      expected,
    }) => {
      const result = getPasswordErrorKey(password)
      expect(result).toBe(expected)
    })
  })
})
